import React, { useState, useMemo } from 'react';
import { motion } from 'framer-motion';
import { Search, CalendarCheck } from 'lucide-react';
import AgentBookingCard from '../components/AgentBookingCard';

const mockBookings = [
  { id: 'COM-001', bookingId: 'BK-001', customer: 'Arjun Sharma', package: 'Golden Triangle Tour', travelDate: '2026-04-20', amount: 45000, commission: 3600, commissionRate: 8, status: 'confirmed', travelers: 4 },
  { id: 'COM-002', bookingId: 'BK-002', customer: 'Priya Patel', package: 'Kerala Backwaters', travelDate: '2026-04-22', amount: 38500, commission: 3080, commissionRate: 8, status: 'pending', travelers: 2 },
  { id: 'COM-003', bookingId: 'BK-003', customer: 'Rahul Gupta', package: 'Goa Beach', travelDate: '2026-04-18', amount: 22000, commission: 1760, commissionRate: 8, status: 'completed', travelers: 6 },
  { id: 'COM-004', bookingId: 'BK-004', customer: 'Ananya Singh', package: 'Manali Trek', travelDate: '2026-04-25', amount: 31000, commission: 2480, commissionRate: 8, status: 'confirmed', travelers: 3 },
  { id: 'COM-005', bookingId: 'BK-005', customer: 'Vikram Reddy', package: 'Andaman Explorer', travelDate: '2026-05-02', amount: 55000, commission: 4400, commissionRate: 8, status: 'pending', travelers: 2 },
  { id: 'COM-006', bookingId: 'BK-006', customer: 'Kavya Nair', package: 'Rajasthan Heritage', travelDate: '2026-04-28', amount: 41500, commission: 3320, commissionRate: 8, status: 'cancelled', travelers: 5 },
];

const STATUSES = ['all', 'confirmed', 'pending', 'completed', 'cancelled'];

const AgentBookingsPage = () => {
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');

  const filtered = useMemo(() => {
    return mockBookings.filter((b) => {
      const matchSearch = b.customer.toLowerCase().includes(search.toLowerCase()) ||
        b.bookingId.toLowerCase().includes(search.toLowerCase()) ||
        b.package.toLowerCase().includes(search.toLowerCase());
      const matchStatus = statusFilter === 'all' || b.status === statusFilter;
      return matchSearch && matchStatus;
    });
  }, [search, statusFilter]);

  const totalCommission = filtered.reduce((s, b) => s + (b.commission || 0), 0);

  return (
    <div className="min-h-screen bg-gray-50 p-4 sm:p-6 lg:p-8">
      <motion.div initial={{ opacity: 0, y: -10 }} animate={{ opacity: 1, y: 0 }} className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-6">
        <div>
          <h1 className="text-2xl font-bold text-gray-900">My Bookings</h1>
          <p className="text-sm text-gray-500">{filtered.length} bookings • ₹{totalCommission.toLocaleString('en-IN')} total commission</p>
        </div>
      </motion.div>

      {/* Filters */}
      <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-4 mb-5">
        <div className="flex flex-col sm:flex-row gap-3">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
            <input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search by customer, booking ID, package..." className="w-full pl-9 pr-3 py-2.5 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-[#0B4F6C]/30 focus:border-[#0B4F6C]" />
          </div>
          <div className="flex gap-1.5 flex-wrap">
            {STATUSES.map((s) => {
              const colors = { all: '', confirmed: 'bg-blue-600 text-white', pending: 'bg-amber-500 text-white', completed: 'bg-emerald-600 text-white', cancelled: 'bg-red-500 text-white' };
              return (
                <button key={s} onClick={() => setStatusFilter(s)} className={`px-3 py-2 text-xs font-medium rounded-lg capitalize transition-all ${statusFilter === s ? (colors[s] || 'bg-gray-800 text-white') : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`}>
                  {s}
                </button>
              );
            })}
          </div>
        </div>
      </div>

      {filtered.length === 0 ? (
        <div className="py-16 text-center bg-white rounded-xl border border-gray-100">
          <CalendarCheck className="w-12 h-12 text-gray-300 mx-auto mb-3" />
          <p className="text-gray-500 font-medium">No bookings found</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 gap-4">
          {filtered.map((booking) => (
            <AgentBookingCard key={booking.id} booking={booking} />
          ))}
        </div>
      )}
    </div>
  );
};

export default AgentBookingsPage;
